-- Passos 2-5 (Adriana, 24/09/2026): pessoas sem empresa com e-mail corporativo -> empresa pelo domínio.
-- Decisão por domínio: empresa do HubSpot quando existe (nome do HubSpot; 3 nomes-sujeira do HubSpot
-- — Sp, Vb, Zf — gravam o nome correto e vão para o passo 10), senão empresa já existente em
-- pessoas.empresas (domínio ou nome_chave), senão empresa nova (Lusha quando houve match; busca na web).
create temp table _m (dom_email text, dom_emp text, nome text, hs text, forcar boolean, lusha_id text, func int,
  setor_bruto text, setor text, cidade text, uf text, pais text, porte text) on commit drop;
-- empresa alvo
alter table _m add column eid uuid;
update _m set eid = e.id from pessoas.empresas e where _m.hs is not null and e.hubspot_company_id = _m.hs;
update _m set eid = (select e.id from pessoas.empresas e where lower(e.dominio) = _m.dom_emp order by e.hubspot_company_id nulls last limit 1)
 where eid is null;
update _m set eid = (select e.id from pessoas.empresas e where e.nome_chave = intelligence.texto_chave(_m.nome, true) order by e.hubspot_company_id nulls last limit 1)
 where eid is null;
create temp table _novas on commit drop as
 select distinct on (dom_emp) dom_emp, nome, lusha_id, func, setor_bruto, setor, cidade, uf, pais, porte from _m where eid is null order by dom_emp, lusha_id nulls last;
 select nome, dom_emp, setor, setor_bruto, func, cidade, uf, pais, 'dominio', lusha_id,
        case when lusha_id is not null then 'lusha' end, case when lusha_id is not null then now() end, true
   from _novas;
update _m set eid = e.id from pessoas.empresas e where _m.eid is null and e.origem='dominio' and lower(e.dominio) = _m.dom_emp;
-- pessoas
create temp table _p on commit drop as
 select p.id, p.empresa antes_empresa, p.empresa_id antes_id, m.eid, case when m.forcar then m.nome else e.nome end nome_final
   from pessoas.pessoas p
   join _m m on lower(split_part(p.email,'@',2)) = m.dom_email
   join pessoas.empresas e on e.id = m.eid
  where p.fundida_em is null and coalesce(btrim(p.empresa),'') = '';
update pessoas.pessoas p set empresa = x.nome_final, empresa_id = x.eid, atualizado_em = now() from _p x where p.id = x.id;
 select 'atualizar','pessoas_empresa_dominio', x.id::text, 'empresa pelo domínio do e-mail',
        jsonb_build_object('empresa', x.antes_empresa, 'empresa_id', x.antes_id), jsonb_build_object('empresa', x.nome_final, 'empresa_id', x.eid),
        '6b1f3c2e-2409-4e2a-9d05-240924000005'::uuid
   from _p x;
select (select count(*) from _novas) empresas_novas, (select count(*) from _p) pessoas_gravadas,
       (select count(*) from _m where eid is null) dominios_sem_empresa;
